with 
User_Answer_Count as (
    select 
        u.Id as UserId,
        cast(count(p.Id) as int) as AnswerCount,
        cast(count(case when p.Score > 10 then 1 end) as int) as HighScoreAnswers
    from Users u
    left join Posts p on p.OwnerUserId = u.Id and p.PostTypeId = 2
    group by u.Id
